namespace App\Http\Requests\Products;use App\Domain\Products\ProductRegistry;use App\Domain\PublicChrome\{PublicAssetPath,PublicLink};use App\Models\{Product,ProductCategory,WebsiteSetting};use Closure;use Illuminate\Foundation\Http\FormRequest;use Illuminate\Support\Str;use Illuminate\Validation\Rule;class SaveProductRequest extends FormRequest {public function authorize():bool{return $this->user()!==null;}protected function prepareForValidation():void{$raw=(string)$this->input('slug');$this->merge(['slug'=>(str_contains($raw,'/')||str_contains($raw,'\\')||str_contains($raw,'..'))?'':Str::slug(Str::lower(trim($raw))),'is_featured'=>$this->boolean('is_featured'),'robots_index'=>$this->boolean('robots_index'),'robots_follow'=>$this->boolean('robots_follow')]);}public function rules():array{$p=$this->route('product');$asset=fn(string $a,mixed $v,Closure $f)=>PublicAssetPath::isSafe(is_string($v)?$v:null)?:$f('Use an approved local image path.');$url=fn(string $a,mixed $v,Closure $f)=>$v&&!PublicLink::isSafeUrl((string)$v)?$f('Use a safe relative or HTTP/HTTPS URL.'):null;$rules=['product_category_id'=>['nullable',Rule::exists(ProductCategory::class,'id')],'title'=>['required','string','max:160'],'slug'=>['required','max:160','regex:/^[a-z0-9]+(?:-[a-z0-9]+)*$/',Rule::unique(Product::class)->ignore($p),fn($a,$v,$f)=>in_array($v,ProductRegistry::RESERVED,true)?$f('This slug is reserved.'):null],'eyebrow'=>['nullable','string','max:120'],'short_description'=>['required','string','max:500'],'overview'=>['nullable','string','max:20000'],'problem_statement'=>['nullable','string','max:10000'],'value_proposition'=>['nullable','string','max:10000'],'icon'=>['nullable',Rule::in(ProductRegistry::ICONS)],'featured_image_path'=>['nullable','string','max:255',$asset],'featured_image_alt'=>['nullable','required_with:featured_image_path','string','max:160'],'hero_style'=>['required',Rule::in(ProductRegistry::HERO_STYLES)],'template'=>['required',Rule::in(ProductRegistry::TEMPLATES)],'is_featured'=>['boolean']];foreach(['primary','secondary','demo'] as $c){$rules[$c.'_cta_label']=['nullable','required_with:'.$c.'_cta_url','string','max:80'];$rules[$c.'_cta_url']=['nullable','required_with:'.$c.'_cta_label','string','max:2048',$url];}$rules+=['documentation_url'=>['nullable','string','max:2048',$url],'meta_title'=>['nullable','string','max:70'],'meta_description'=>['nullable','string','max:170'],'canonical_url'=>['nullable','url:http,https','max:2048',function($a,$v,$f){$site=WebsiteSetting::value('site_url');if($v&&$site&&strcasecmp((string)parse_url($v,PHP_URL_HOST),(string)parse_url($site,PHP_URL_HOST))!==0)$f('Canonical URL must use the website host.');}],'og_title'=>['nullable','string','max:70'],'og_description'=>['nullable','string','max:200'],'og_image_path'=>['nullable','string','max:255',$asset],'robots_index'=>['boolean'],'robots_follow'=>['boolean']];return $rules;}}